mapper.select:
SELECT CAST(r.id AS VARCHAR) AS id, CAST(r.enterprise_id AS VARCHAR) AS enterprise_id, e.enterprise_code, e.tenant_code, r.apply_no, r.version_no, CAST(r.applicant_id AS VARCHAR) AS applicant_id, r.company_name, r.industry, r.scale, r.contact_name, r.contact_phone, r.contact_email, r.license_no, r.register_address, r.legal_person, CAST(r.license_file_id AS VARCHAR) AS license_file_id, r.status, r.reject_reason, CAST(r.reviewer_id AS VARCHAR) AS reviewer_id, r.review_time, r.submit_time, e.status AS enterprise_status FROM enterprise_review r JOIN enterprise e ON e.id = r.enterprise_id AND e.is_deleted = FALSE WHERE r.is_deleted = FALSE AND r.status = #{status}
AND (r.company_name ILIKE CONCAT('%', #{keyword}, '%') OR r.apply_no ILIKE CONCAT('%', #{keyword}, '%') OR r.contact_name ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.submit_time DESC, r.id DESC
